/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] 卡片 Card
 *
 * 来源:uiux-atlas src/content/entries/components/card/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

const css = `
.cd-scene { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; padding: 20px 16px; }
/* 卡片:1px 边框 = antd variant outlined;阴影默认轻阴影档 boxShadowTertiary */
.cd-card {
  width: min(380px, 100%);
  background: #fff; border: 1px solid #d9d9d9; border-radius: 8px; /* 圆角 LG = seed 6 +2 */
  box-shadow: 0 1px 2px 0 rgba(0,0,0,0.05), 0 1px 6px -1px rgba(0,0,0,0.03), 0 2px 4px 0 rgba(0,0,0,0.03);
  animation: cd-in 0.4s cubic-bezier(0.215, 0.61, 0.355, 1) both;
}
/* hoverable:升到浮层阴影档 boxShadow(06-antdesign.md §2.3 ⑥)+ 2px 上浮 */
.cd-card[data-hoverable="on"] {
  cursor: pointer;
  transition: box-shadow 0.2s cubic-bezier(0.215, 0.61, 0.355, 1), translate 0.2s cubic-bezier(0.215, 0.61, 0.355, 1);
}
.cd-card[data-hoverable="on"]:hover {
  box-shadow: 0 6px 16px 0 rgba(0,0,0,0.08), 0 3px 6px -4px rgba(0,0,0,0.12), 0 9px 28px 8px rgba(0,0,0,0.05);
  translate: 0 -2px;
}
/* 封面:纯装饰渐变色带(cover 插槽的演示形态) */
.cd-cover {
  height: 92px; border-radius: 8px 8px 0 0;
  background:
    radial-gradient(90% 140% at 12% 8%, oklch(0.78 0.13 220 / 0.9), transparent 62%),
    radial-gradient(80% 130% at 88% 16%, oklch(0.75 0.14 285 / 0.85), transparent 60%),
    oklch(0.55 0.12 250);
}
/* 头部:标题 + extra */
.cd-head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  border-bottom: 1px solid #f0f0f0; /* colorBorderSecondary */
}
.cd-card[data-size="md"] .cd-head { padding: 16px 24px; }
.cd-card[data-size="sm"] .cd-head { padding: 10px 12px; }
.cd-title { margin: 0; font-weight: 600; color: rgba(0, 0, 0, 0.88); }
.cd-card[data-size="md"] .cd-title { font-size: 16px; }
.cd-card[data-size="sm"] .cd-title { font-size: 14px; }
.cd-extra { font-size: 12px; color: #1677ff; white-space: nowrap; } /* antd colorPrimary */
/* 正文 */
.cd-body { color: rgba(0, 0, 0, 0.65); line-height: 1.6; }
.cd-card[data-size="md"] .cd-body { padding: 16px 24px; font-size: 14px; }
.cd-card[data-size="sm"] .cd-body { padding: 10px 12px; font-size: 13px; }
.cd-body p { margin: 0; }
/* 操作区:顶部细分隔线,均分三个动作(antd actions 形态) */
.cd-actions {
  display: flex; border-top: 1px solid #f0f0f0;
}
.cd-actions button {
  flex: 1; border: 0; background: none; cursor: pointer;
  color: rgba(0, 0, 0, 0.65); font-size: 13px; padding: 9px 0;
  display: inline-flex; align-items: center; justify-content: center; gap: 5px;
}
.cd-card[data-size="md"] .cd-actions button { padding: 12px 0; }
.cd-actions button + button { border-left: 1px solid #f0f0f0; }
.cd-actions button:hover { color: #1677ff; }
.cd-actions button:focus-visible { outline: 2px solid #1677ff; outline-offset: -2px; }
.cd-note { margin-top: 10px; font-size: 11px; color: rgba(0, 0, 0, 0.45); text-align: center; }
@keyframes cd-in { from { opacity: 0; translate: 0 8px; } to { opacity: 1; translate: 0 0; } }
@media (prefers-reduced-motion: reduce) {
  .cd-card { animation: none; }
  .cd-card[data-hoverable="on"] { transition: none; }
}
`;

/**
 * 卡片演示:size / hoverable / cover 均为 JS 型参数(订阅 store 切 data-* 属性)。
 * 结构:可选封面带 → 头部(标题+extra)→ 正文 → 操作区;hoverable 切换 antd 双阴影档。
 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [size, setSize] = useState(() => store.get("size") as string);
  const [hoverable, setHoverable] = useState(() => store.get("hoverable") as string);
  const [cover, setCover] = useState(() => store.get("cover") as string);

  useEffect(
    () =>
      store.subscribe(() => {
        setSize(store.get("size") as string);
        setHoverable(store.get("hoverable") as string);
        setCover(store.get("cover") as string);
      }),
    [store],
  );

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="cd-scene">
        <figure style={{ margin: 0 }}>
          <article className="cd-card" data-size={size} data-hoverable={hoverable}>
            {cover === "on" && <div className="cd-cover" aria-hidden="true" />}
            <header className="cd-head">
              <h3 className="cd-title">设计周报 Design Weekly</h3>
              <a className="cd-extra" href="#more" onClick={(e) => e.preventDefault()}>
                更多 More
              </a>
            </header>
            <div className="cd-body">
              <p>
                本周聚焦卡片容器的层级表达:outlined 形态靠 1px 边框划界,浮起形态靠阴影升档——两者是同一层级的两种说法。
              </p>
            </div>
            <footer className="cd-actions">
              <button type="button">赞 128</button>
              <button type="button">评论 32</button>
              <button type="button">分享</button>
            </footer>
          </article>
          <figcaption className="cd-note">
            {hoverable === "on" ? "hoverable:整卡浮起(阴影升档 + 2px 上移)" : "静态卡:hoverable=off(antd 默认)"} ·
            {cover === "on" ? " 封面色带开启" : " 无封面"} · {size === "sm" ? "紧凑 sm" : "标准 md"}
          </figcaption>
        </figure>
      </div>
      <style>{css}</style>
    </DemoStage>
  );
}
